def gen(rng):
    def fmt(vals, pos):
        return str(len(vals)) + '\n' + ' '.join(map(str, vals)) + '\n' + str(pos)
    def vals(n, lo=-1000, hi=1000):
        return [rng.randint(lo, hi) for _ in range(n)]
    tests = [fmt([1], -1), fmt([1], 0), fmt([1, 2], -1), fmt([1, 2], 0), fmt([1, 2], 1), fmt([5, 5, 5], 0), fmt([5, 5, 5], 2), fmt([3, 8, 1, 8, 4], 1), fmt([7, 7, 7], -1), fmt([5, 6, 7, 8], 3)]
    for n in (3, 4, 5, 6, 8, 10, 14, 20):
        for _ in range(3):
            tests.append(fmt(vals(n, -5, 5), rng.randint(-1, n - 1)))
    N = 100000
    tests.append(fmt(vals(N), -1))
    tests.append(fmt(vals(N), 0))
    tests.append(fmt(vals(N), N // 2))
    tests.append(fmt(vals(N), N - 1))
    tests.append(fmt(vals(N, 0, 1), N - 2))
    return tests
